template <typename T>
struct is_pointer {
    static constexpr bool value = false;
};

// Full specialization for pointer types (T*)
template <typename T>
struct is_pointer<T*> {
    static constexpr bool value = true;
};

// --- Usage ---
// Provides 'is_pointer<T>::value' trait

static_assert(is_pointer<int*>::value, "");
static_assert(!is_pointer<int>::value, "");

// C++17 helper alias
template <typename T>
inline constexpr bool is_pointer_v = is_pointer<T>::value;
